// PR · NAZORATCHI — barcha chegaralar $json.qoidalar va $json.platforma_qoida dan (kodda qattiq raqam yo'q).
var j = $json, X = [];
var q = j.qoidalar || {}, pq = j.platforma_qoida || {}, mk = j.mahsulot_kod;
var EPS = 0.001; // faqat suzuvchi nuqta xatosi uchun
function yol(o, p){ return String(p).split(".").reduce(function(a, k){ return a == null ? undefined : a[k]; }, o); }
function kerak(v, nom){ if (v == null || (typeof v === "number" && isNaN(v))) { X.push("qoida topilmadi: " + nom); return null; } return v; }
function r1(x){ return Math.round(x * 10) / 10; }
function t0(s){ return Number(s.boshlanish_s) || 0; }
function t1(s){ return t0(s) + (Number(s.davomiylik_s) || 0); }
function tok(s){ return String(s || "").toLocaleLowerCase("tr").replace(/[^\p{L}\p{N}\s]+/gu, "").split(/\s+/).filter(Boolean); }
function sozSoni(s){ return String(s || "").split(/\s+/).filter(function(w){ return /[\p{L}\p{N}]/u.test(w); }).length; }
if (j.xato) X.push("PARSE_FAIL: prodyuser javobi JSON emas — faqat JSON qaytar");
var S = ((j.reja || {}).sahnalar) || [];
if (!j.xato && !S.length) X.push("reja.sahnalar bo'sh");
var MANBA_V = ["V_MANBA_KARTA", "V_MANBA_SAHIFA"];
var KUTUB = ["V_DONUT","V_WAFFLE","V_ORALIQ","V_USTUN","V_CHIZIQ","V_SXEMA","V_KATTA_RAQAM","V_MANBA_KARTA","V_MANBA_SAHIFA","V_KALIT_SOZ","V_AVATAR_TOLIQ","V_GIBRID"];
var mh = $("PR · manba_havolalari").all().map(function(i){ return i.json; });
var fIds = (j.faktlar || []).map(function(f){ return f.s_id; });
function nom(s, i){ return (s.n || i + 1) + "-sahna"; }
if (S.length) {
  // a) ilgak
  var ilgak = kerak(pq.ilgak_s, "platforma_qoida.ilgak_s");
  if (ilgak != null && t1(S[0]) > ilgak + EPS) { var sz = ((j.vaqt || {}).sozlar || []).filter(function(x, k){ return k > 0 && x.t <= ilgak + EPS; }); var tavsiya = sz.length ? sz[sz.length - 1] : null; X.push("a) 1-sahna " + r1(t1(S[0])) + " s da tugaydi, ilgak ≤ " + ilgak + " s bo'lishi kerak — 2-sahna ≤ " + ilgak + " s da boshlansin" + (tavsiya ? ": 2-sahna sinxron_soz'i \"" + tavsiya.w + "\" (" + tavsiya.t + " s) yoki undan oldingi so'z bo'lsin" : "")); }
  var v0 = String(S[0].vizual || "");
  if (!/^V_/.test(v0) || v0 === "V_AVATAR_TOLIQ" || MANBA_V.indexOf(v0) >= 0) X.push("a) 1-sahnada grafik (V_*) yo'q: " + (v0 || "—"));
  // b) yolg'iz avatar
  var avMax = kerak(yol(q, "avatar.uzluksiz_kadr_max_s." + mk), "qoidalar.avatar.uzluksiz_kadr_max_s." + mk);
  var run = 0, runN = null;
  S.forEach(function(s, i){ var yz = s.vizual === "V_AVATAR_TOLIQ"; if (yz) { run += Number(s.davomiylik_s) || 0; if (runN == null) runN = nom(s, i); } if (!yz || i === S.length - 1) { if (avMax != null && run > avMax + EPS) X.push("b) yolg'iz avatar kadri (" + runN + " dan) " + r1(run) + " s, maks " + avMax + " s — grafikka o't"); run = 0; runN = null; } });
  // c) patern uzish
  var pat = kerak(yol(q, "neyro.patern_uzish_s." + mk), "qoidalar.neyro.patern_uzish_s." + mk);
  var jami = t1(S[S.length - 1]) - t0(S[0]), seg = 1;
  for (var k = 1; k < S.length; k++) if (S[k].vizual !== S[k - 1].vizual) seg++;
  var ort = seg ? jami / seg : jami;
  if (pat != null && ort > pat + EPS) X.push("c) vizual almashishlar orasidagi o'rtacha vaqt " + r1(ort) + " s (" + seg + " ta vizual, " + r1(jami) + " s), maks " + pat + " s");
  S.forEach(function(s, i){ if (!((Number(s.davomiylik_s) || 0) > EPS)) X.push("c) " + nom(s, i) + " davomiyligi 0 s — sinxron_soz TTS matnidagi aniq so'z bo'lsin va oldingi sahnaning sinxron_soz'idan keyin kelsin"); });
  var ekMax = kerak(yol(q, "kognitiv.ekran_matni_soz_max"), "qoidalar.kognitiv.ekran_matni_soz_max");
  var kech = kerak(yol(q, "manba.da_vo_manba_kechikish_s"), "qoidalar.manba.da_vo_manba_kechikish_s");
  var korilgan = [];
  var taqiq = yol(q, "huquq.taqiq") || [], ibora = [];
  taqiq.forEach(function(t){ String(t).split("/").forEach(function(p){ var w = tok(p); if (w.length) ibora.push(w.slice(0, 2).join(" ")); }); });
  var akk = (((j.vizual_tizim || {}).akkaunt || {})[j.akkaunt] || {}).taqiq_sozlar || [];
  var ruxsatHavola = mh.map(function(r){ return r.havola; }).filter(Boolean);
  var eslatma = []; // PR-6.9-hotfix: forEach ichida ishlatiladi, oldinroq e'lon qilinishi kerak
  S.forEach(function(s, i){
    var n = nom(s, i), ek = String(s.ekran_yozuvi || ""), isM = MANBA_V.indexOf(s.vizual) >= 0;
    if (KUTUB.indexOf(s.vizual) < 0) X.push("i) " + n + ": vizual kutubxonada yo'q — " + s.vizual);
    // d) ekran yozuvi
    if (ekMax != null && sozSoni(ek) > ekMax) X.push("d) " + n + " ekran_yozuvi " + sozSoni(ek) + " so'z, maks " + ekMax);
    if (tok(ek).length && tok(ek).join(" ") === tok(s.tts_parcha).join(" ")) X.push("d) " + n + " ekran_yozuvi tts_parcha bilan so'zma-so'z bir xil — faqat kalit so'z/raqam qoldir");
    // e) raqam → vizual
    // PR-6.9b: matn-asosli (ekran_yozuvi) foiz/oraliq qoidalari olib tashlandi - endi ekran raqami kod (fakt.ekran) dan, rk-asosli tekshiruv yetarli
    var md = s.malumot || {}, sonli = function(L){ return (L || []).map(function(x){ return typeof x === "object" && x ? Number(x.qiymat) : Number(x); }).filter(function(x){ return !isNaN(x); }).length; };
    if (s.vizual === "V_USTUN" && sonli(md.ustunlar || md.degerler) < 2) X.push("e) " + n + ": V_USTUN uchun malumot.ustunlar ≥2 son (faktlardan) kerak");
    if (s.vizual === "V_CHIZIQ" && (sonli(md.a) < 2 || sonli(md.b) < 2)) X.push("e) " + n + ": V_CHIZIQ uchun malumot.a va malumot.b — har biri ≥2 son kerak");
    if (s.vizual === "V_SXEMA" && !((md.qadamlar || md.tugunlar || []).length >= 3 && (md.qadamlar || md.tugunlar).length <= 4)) X.push("e) " + n + ": V_SXEMA uchun malumot.qadamlar — 3–4 ta blok matni kerak");
    var rk = s.raqam_kod; // kod rejasidagi ovozdagi raqam
    if (rk && s.s_id && !isM) {
      if (rk.oraliq && s.vizual !== "V_ORALIQ") X.push("e) " + n + ": ovozdagi raqam oraliq (" + rk.metin + ") → V_ORALIQ");
      else if (!rk.oraliq && (rk.foiz || rk.nisbat) && ["V_DONUT", "V_WAFFLE"].indexOf(s.vizual) < 0) X.push("e) " + n + ": ovozdagi raqam foiz/nisbat (" + rk.metin + ") → V_DONUT yoki V_WAFFLE"); // PR-6.9a: nisbat ham ulush
      else if (!rk.oraliq && !rk.foiz && !rk.nisbat && ["V_KATTA_RAQAM", "V_USTUN", "V_CHIZIQ"].indexOf(s.vizual) < 0) X.push("e) " + n + ": ovozdagi foizsiz raqam (" + rk.metin + ") → V_KATTA_RAQAM (yoki V_USTUN/V_CHIZIQ)"); // PR-6.9a: nisbat bo'lsa bu qoida qo'llanilmaydi
    }
    if (rk && s.s_id && isM) X.push("e) " + n + ": ovozda raqam bor (" + rk.metin + ") — sahna grafik bo'lsin, manba esa manba_vizual orqali");
    if (s.vizual === "V_KATTA_RAQAM" && !s.raqam_juft) { var qoshni = function(dir){ for (var q = i + dir; q >= 0 && q < S.length; q += dir) { if (MANBA_V.indexOf(S[q].vizual) < 0) return S[q]; } return null; }; var juft = [qoshni(-1), qoshni(1)].filter(Boolean).some(function(x){ return x.vizual === "V_DONUT" || x.vizual === "V_WAFFLE"; }); /* manba kartasi juftlikni uzmaydi */ if (!juft) eslatma.push("e) " + n + ": V_KATTA_RAQAM yolg'iz — qo'shni sahnada V_DONUT yoki V_WAFFLE bo'lsin yoki boshqa vizual tanla"); } // PR-8.2: FAIL emas endi, faqat eslatma; s.raqam_juft bo'lsa (kod avtomatik juftlagan) - hech narsa yozilmaydi
    // f) raqam → s_id → manba vizuali
    if (rk && !isM) { if (!s.s_id) X.push("f) " + n + ": ekranda raqam bor, s_id yo'q"); else if (fIds.indexOf(s.s_id) < 0) X.push("f) " + n + ": s_id faktlarda yo'q — " + s.s_id); } // PR-6.9b-fix: sonlar (matn-asosli, olib tashlangan) o'rniga rk (kod-asosli raqam_kod)
    if (s.s_id && !isM && korilgan.indexOf(s.s_id) < 0 && kech != null) {
      korilgan.push(s.s_id);
      var ok = MANBA_V.indexOf(s.manba_vizual) >= 0 || S.some(function(m){ return MANBA_V.indexOf(m.vizual) >= 0 && m.s_id === s.s_id && t0(m) >= t0(s) - EPS && t0(m) <= t1(s) + kech + EPS; });
      if (!ok) X.push("f) " + n + " da'vosi (" + s.s_id + ") dan keyin ≤ " + kech + " s ichida manba vizuali yo'q");
    }
    // g) V_MANBA_SAHIFA ruxsati
