// PR to'siq (guard) - yuborishdan OLDIN chat va thread qattiq tekshiriladi.
// Sabab: DZ studiyasida test_rejim yo'qolib, rasm production threadga ketgan edi.
// TUZATISH (PR-5.2 topilmasi): ba'zi filiallarda (masalan xato/eskalatsiya) item'da 'thread' maydoni umuman bo'lmaydi -
// Telegram node'ida u baribir Fixed=427 bo'lgani uchun bu holat FAIL emas. Faqat thread MAVJUD va 427 dan farqli bo'lsa FAIL.
var CHAT_ID = -1004462774154;
var THREAD_ID = 427;

var out = [];
for (const item of $input.all()) {
  var thread = item.json.thread;
  var chat = (item.json.chat !== undefined && item.json.chat !== null) ? item.json.chat : CHAT_ID;
  var threadBad = (thread !== undefined && thread !== null) && Number(thread) !== THREAD_ID;
  var chatBad = Number(chat) !== CHAT_ID;
  if (chatBad || threadBad) {
    throw new Error("PR to'siq: FAIL - yuborilmadi. chat=" + chat + " (kutilgan " + CHAT_ID + "), thread=" + thread + " (kutilgan " + THREAD_ID + " yoki mavjud emas). job_id=" + item.json.job_id);
  }
  out.push(item);
}
return out;

